function normalizeAdzunaItem(raw) {
    return {
      source: 'adzuna.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company ? raw.company.display_name : null,
      url: raw.redirect_url,
      location: raw.location ? raw.location.display_name : null,
      posted_at: raw.created ? raw.created.slice(0, 10) : null,
      raw_extra: {
        description_snippet: raw.description || null,
        salary_min: raw.salary_min || null,
        salary_max: raw.salary_max || null,
        contract_type: raw.contract_type || null,
        contract_time: raw.contract_time || null,
        category: raw.category ? raw.category.label : null,
        description_full: raw.fullDescription || null,
      },
    };
  }

  // Un item par mot-clé du profil (Split Out en amont) : chaque item est la
      // réponse Adzuna d'UN mot-clé. Ne lire que items[0] ignorait silencieusement
      // tous les mots-clés sauf le premier.
      return items.flatMap(item => {
        const input = item.json;
        if (!input || !Array.isArray(input.results)) {
          // Échec isolé à cette seule source (pas de throw) : les autres sources
          // et le digest ne doivent pas être bloqués par une panne Adzuna. Le node
          // "If Adzuna OK" juste après route ce marqueur vers une alerte par email.
          return [{ json: { __sourceError: true, source: 'Adzuna', message: 'réponse inattendue — ' + JSON.stringify(input).slice(0, 500) } }];
        }
        return input.results.map(raw => ({ json: normalizeAdzunaItem(raw) }));
      });

function normalizeJoobleItem(raw) {
    return {
      source: 'jooble.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company || null,
      url: raw.link,
      location: raw.location || null,
      posted_at: raw.updated ? raw.updated.slice(0, 10) : null,
      raw_extra: {
        description_snippet: raw.snippet || null,
        salary: raw.salary || null,
        type: raw.type || null,
        source_name: raw.source || null,
        description_full: raw.fullDescription || null,
      },
    };
  }

  // Un item par mot-clé — voir le commentaire équivalent dans "Normalize Adzuna".
      return items.flatMap(item => {
        const input = item.json;
        if (!input || !Array.isArray(input.jobs)) {
          return [{ json: { __sourceError: true, source: 'Jooble', message: 'réponse inattendue — ' + JSON.stringify(input).slice(0, 500) } }];
        }
        return input.jobs.map(raw => ({ json: normalizeJoobleItem(raw) }));
      });

function ensureUrlScheme(u) {
    // Job-Room agrège des annonces externes dont externalUrl arrive parfois
    // sans schéma (ex: "www.jobs.ch/de/..." au lieu de "https://www.jobs.ch/de/...").
    // safeUrl() dans "Formater Digest" rejette silencieusement tout ce qui ne
    // matche pas ^https?:// et retombe sur "#" — le bouton "Voir l'offre" du
    // digest devient alors inerte sans erreur ni log. On corrige à la source.
    if (!u) return u;
    return /^https?:\/\//i.test(u) ? u : 'https://' + u;
  }

  function cleanHtml(s) {
    if (!s) return null;
    return String(s).replace(/<[^>]*>/g, '').trim();
  }

  function normalizeJobRoomItem(raw) {
    const ad = raw.jobAdvertisement;
    const content = ad.jobContent || {};
    const descriptions = content.jobDescriptions || [];
    const desc = descriptions.find(d => d.languageIsoCode === 'fr') || descriptions[0] || {};
    const location = content.location || {};
    return {
      source: 'job-room.ch',
      source_id: ad.id,
      title: cleanHtml(desc.title),
      company: content.company ? content.company.name : null,
      url: ensureUrlScheme(content.externalUrl) || ('https://www.job-room.ch/job-search/detail/' + ad.id),
      location: [location.city, location.cantonCode].filter(Boolean).join(', ') || null,
      posted_at: ad.createdTime ? ad.createdTime.slice(0, 10) : null,
      raw_extra: {
        description_snippet: cleanHtml(desc.description) || null,
        canton: location.cantonCode || null,
      },
    };
  }

  // n8n éclate automatiquement une réponse HTTP dont le corps est un tableau
  // JSON en un item par élément — chaque items[i].json est donc déjà UNE
  // offre ({ jobAdvertisement: {...}, favouriteItem: null }), jamais le
  // tableau complet. Aucun résultat pour ce mot-clé donne simplement zéro
  // item (pas une erreur).
  if (items.length === 0) return [];

  const malformed = items.find(item => !item.json || !item.json.jobAdvertisement);
  if (malformed) {
    // Échec explicite plutôt qu'avalé silencieusement — voir le commentaire
    // équivalent dans "Normalize Adzuna".
    return [{ json: { __sourceError: true, source: 'Job-Room', message: 'réponse inattendue — ' + JSON.stringify(malformed.json).slice(0, 500) } }];
  }

  // Certaines annonces EXTERN (agrégées depuis un autre portail) arrivent
  // avec un champ title corrompu par Job-Room — un fragment de description
  // ("&nbsp;", "*  02 août 2026", "## VOTRE RÔLE ##", "Nous recherchons...")
  // au lieu d'un vrai intitulé de poste. On écarte ces annonces plutôt que de
  // les afficher telles quelles dans le digest.
  function looksLikeGarbageTitle(title) {
    if (!title) return true;
    const t = title.trim();
    if (t.length < 3 || t.length > 140) return true;
    return /^(&nbsp;|[*#,]|nous recherchons|entreprise|afin de|ce poste)/i.test(t);
  }

  return items
    .map(item => normalizeJobRoomItem(item.json))
    .filter(job => !looksLikeGarbageTitle(job.title))
    .map(job => ({ json: job }));

// Un item par mot-clé (Split Out en amont) : chaque items[i].json.data est la
    // page de résultats HTML d'UN mot-clé. Ne lire que items[0] ignorait
    // silencieusement les pages de tous les autres mots-clés.
    const pattern = new RegExp('<script type="application/ld\\+json">(.*?)<\\/script>', 's');

    function extractJobs(html) {
      const match = String(html || '').match(pattern);
      if (!match) return [];
      const ldJson = JSON.parse(match[1]);
      const itemList = ldJson.find(entry => entry['@type'] === 'ItemList');
      if (!itemList) return [];
      return itemList.itemListElement.map(entry => {
        const job = entry.item;
        return {
          json: {
            id: job.identifier ? job.identifier.value : null,
            title: job.title,
            company: job.hiringOrganization ? job.hiringOrganization.name : null,
            url: job.url,
            location: job.jobLocation && job.jobLocation.address ? job.jobLocation.address.addressLocality || null : null,
            postedDate: job.datePosted ? job.datePosted.slice(0, 10) : null,
            contractType: job.employmentType || null,
            remote: null,
            description: job.description || null,
          },
        };
      });
    }

    const results = items.flatMap(item => extractJobs(item.json.data));

    // Dédoublonnage dans le scrape du jour, désormais aussi ENTRE mots-clés : une
    // même offre ("Data Engineer DevOps") remonte pour plusieurs mots-clés.
    const seen = new Set();
    const deduped = [];
    for (const item of results) {
      const key = String(item.json.title || '').trim().toLowerCase()
        + '|' + String(item.json.company || '').trim().toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      deduped.push(item);
    }

    return deduped;

function normalizeJobchListing(raw) {
    return {
      source: 'jobs.ch',
      source_id: raw.id,
      title: raw.title,
      company: raw.company,
      url: raw.url,
      location: raw.location,
      posted_at: raw.postedDate || null,
      raw_extra: {
        contract_type: raw.contractType || null,
        remote: raw.remote || null,
        description: raw.description || null,
      },
    };
  }

  return items.map(item => ({ json: normalizeJobchListing(item.json) }));

const FRENCH_WORDS = ['et', 'le', 'la', 'les', 'des', 'pour', 'avec', 'notre', 'nos', 'vous', 'êtes',
  'nous', 'recherchons', 'poste', 'équipe', 'expérience', 'compétences'];
  const GERMAN_WORDS = ['und', 'der', 'die', 'das', 'mit', 'für', 'sind', 'werden', 'sie', 'ihre',
  'unsere', 'kenntnisse', 'erfahrung', 'aufgaben', 'wir', 'suchen', 'stelle', 'unternehmen'];
  const ITALIAN_WORDS = ['e', 'il', 'la', 'di', 'per', 'con', 'sono', 'nostra', 'nostro', 'esperienza',
  'competenze', 'cerchiamo', 'azienda', 'lavoro'];
  const ENGLISH_WORDS = ['the', 'and', 'you', 'our', 'for', 'with', 'are', 'will', 'team', 'looking',
  'join', 'experience', 'skills', 'role', 'we'];

  function buildMarker(words) {
    return new RegExp('\\b(' + words.join('|') + ')\\b', 'gi');
  }

  const FRENCH_MARKERS = buildMarker(FRENCH_WORDS);
  const GERMAN_MARKERS = buildMarker(GERMAN_WORDS);
  const ITALIAN_MARKERS = buildMarker(ITALIAN_WORDS);
  const ENGLISH_MARKERS = buildMarker(ENGLISH_WORDS);

  function searchableText(listing) {
    return [
      listing.title || '',
      listing.raw_extra && (listing.raw_extra.description || listing.raw_extra.description_snippet ||
  listing.raw_extra.description_full) || '',
    ].join(' ').toLowerCase();
  }


  function detectForeignLanguage(listing) {
    const text = searchableText(listing);
    const counts = {
      fr: (text.match(FRENCH_MARKERS) || []).length,
      de: (text.match(GERMAN_MARKERS) || []).length,
      it: (text.match(ITALIAN_MARKERS) || []).length,
      en: (text.match(ENGLISH_MARKERS) || []).length,
    };

    const nonFrenchMax = Math.max(counts.de, counts.it, counts.en);

    if (counts.fr >= 2 && counts.fr >= nonFrenchMax) return null;
    if (nonFrenchMax < 2) return null;

    if (counts.de === nonFrenchMax) return 'de';
    if (counts.it === nonFrenchMax) return 'it';
    return 'en';
  }

    // --- Copie de n8n/logic/job_targeting.js (testé dans tests/logic/job_targeting.test.js) ---
// Ciblage du profil : uniquement les trois métiers visés (data, software,
// devops), uniquement en Suisse romande, et sans les postes seniors.
// Les sources sont interrogées par métier SANS "junior" (jobs.ch, Genève :
// 66 offres "data engineer" contre 2 pour "junior data engineer" — la
// plupart des postes accessibles à un junior ne portent pas la mention), la
// séniorité est donc tranchée ici, localement.

const ROLE_PATTERNS = {
  'data engineer': [
    /\b(big )?data engineer/i,
    /\bdata engineering\b/i,
    /\banalytics engineer/i,
    /\bing[ée]nieur(e|\(e\)|·e)?s? (de |en |des )?donn[ée]es\b/i,
    /\bing[ée]nieur(e|\(e\)|·e)? (big )?data\b/i,
    /\bd[ée]veloppeur(se|\(se\)|·se)? (data|etl|big data)\b/i,
    /\bdata ?ingenieur/i,
    /\bdateningenieur/i,
    /\betl developer/i,
  ],
  'software engineer': [
    /\bsoftware (engineer|developer|entwickler)/i,
    /\bing[ée]nieur(e|\(e\)|·e)? (en |de )?(logiciel|software)/i,
    // "Ingénieur développement" seul couvre aussi la mécanique ("Développement Moteur").
    /\bing[ée]nieur(e|\(e\)|·e)? (en |de )?d[ée]veloppement (logiciel|software|web|full.?stack|back.?end|front.?end|ia|ai|informatique|applicatif)/i,
    /\bfull.?stack\b/i,
    /\bd[ée]veloppeur(se|\(se\)|·se)?\b/i,
    /\b(full.?stack|back.?end|front.?end|web|python|java|\.net|c\+\+) (engineer|developer)\b/i,
    /\bdeveloper\b/i,
    /\bsoftwareentwickler/i,
    /\bprogrammeur/i,
  ],
  'devops engineer': [
    /\bdev ?ops\b/i,
    /\bdev ?sec ?ops\b/i,
    /\bsite reliability\b/i,
    /\bsre\b/i,
    /\bplatform engineer/i,
    /\bcloud engineer/i,
    /\bing[ée]nieur(e|\(e\)|·e)? (cloud|plateforme)\b/i,
  ],
};

// "Business Developer" et "Développeur commercial" contiennent "developer"
// mais sont des postes de vente.
const NOT_A_TECH_ROLE = /\b(business develop|d[ée]veloppeu(r|se) (commercial|d'affaires|business)|d[ée]veloppement (commercial|des affaires)|sales)/i;

const SENIOR_TITLE = /\b(senior|sr\.?|lead|principal|staff|head|chief|manager|director|directeur|directrice|architect|architecte|expert|experte|confirm[ée]e?|exp[ée]riment[ée]e?|chef|cheffe|responsable|vp|leiter|leiterin)\b/i;

const JUNIOR_TITLE = /\b(junior|jr\.?|graduate|entry.level|d[ée]butant(e)?|stage|stagiaire|intern|internship|trainee|apprenti(e)?|apprentissage|alternance|alternant(e)?|working student|werkstudent(in)?|praktikum|praktikant(in)?|jeune dipl[ôo]m[ée](e)?|new grad)\b/i;
const JUNIOR_TEXT = /\b(junior|graduate|entry.level|d[ée]butant(e)?|jeune dipl[ôo]m[ée](e)?|new grad|premi[èe]re exp[ée]rience)\b/i;

// "5+ years of experience", "au moins 4 ans d'expérience", "5 Jahre Erfahrung".
const YEARS_OF_EXPERIENCE = /(\d{1,2})\s*\+?\s*(?:-\s*\d{1,2}\s*)?(?:ans|ann[ée]es|years?|yrs|jahre)\b[^.\n]{0,40}?(exp[ée]rience|experience|erfahrung)/gi;
const MAX_JUNIOR_YEARS = 3;

function profileRole(keyword) {
  return String(keyword || '').toLowerCase().replace(/^\s*junior\s+/, '').trim();
}

function matchedRoles(title, profile) {
  const text = String(title || '');
  if (NOT_A_TECH_ROLE.test(text)) return [];
  return profile.keywords.filter((kw) => {
    const role = profileRole(kw);
    const patterns = ROLE_PATTERNS[role];
    return patterns ? patterns.some((re) => re.test(text)) : text.toLowerCase().includes(role);
  });
}

function requiredYears(text) {
  let max = 0;
  for (const m of String(text || '').matchAll(YEARS_OF_EXPERIENCE)) {
    max = Math.max(max, Number(m[1]));
  }
  return max;
}

// 'junior' : la mention est explicite. 'unspecified' : aucune indication.
// 'senior' : titre senior/lead/architecte..., ou plus de MAX_JUNIOR_YEARS ans
// d'expérience demandés sans mention junior dans le titre.
function seniority(title, description) {
  const juniorTitle = JUNIOR_TITLE.test(title || '');
  if (!juniorTitle && SENIOR_TITLE.test(title || '')) return 'senior';
  if (juniorTitle) return 'junior';
  if (requiredYears(description) > MAX_JUNIOR_YEARS) return 'senior';
  if (JUNIOR_TEXT.test(description || '')) return 'junior';
  return 'unspecified';
}

// Liste blanche plutôt que liste noire : une liste des localités hors
// Romandie n'est jamais complète (Schlieren, Sursee passaient). Une offre
// est gardée si sa localisation cite un canton romand ou une ville du
// profil, ou si elle ne précise rien de plus que le pays (bénéfice du doute).
const ROMAND_CANTONS = /\b(ge|vd|ne|fr|vs|ju|gen[èe]ve|geneva|genf|vaud|waadt|neuch[âa]tel|neuenburg|fribourg|freiburg|valais|wallis|jura)\b/i;
// Le Haut-Valais est germanophone, même s'il est en "VS"/"Wallis".
const UPPER_VALAIS = /\b(brig|brigue|visp|vi[èe]ge|zermatt|naters|leuk|loèche)\b/i;
const COUNTRY_ONLY = /\b(switzerland|suisse|schweiz|svizzera|ch|remote|t[ée]l[ée]travail|hybrid|hybride|kanton|canton)\b/gi;

const LOCATION_ALIASES = {
  'genève': ['genève', 'geneve', 'geneva', 'genf', 'ginevra'],
  'lausanne': ['lausanne', 'losanna'],
  'neuchâtel': ['neuchâtel', 'neuchatel', 'neuenburg'],
  'fribourg': ['fribourg', 'freiburg'],
  'sion': ['sion', 'sitten'],
  'delémont': ['delémont', 'delemont', 'delsberg'],
};

function locationMatches(location, profile) {
  const text = String(location || '').toLowerCase();
  if (!text) return false;
  return profile.locations.some((loc) => {
    const locLower = loc.toLowerCase();
    return (LOCATION_ALIASES[locLower] || [locLower]).some((alias) => text.includes(alias));
  });
}

function isRomandieLocation(location, profile) {
  const text = String(location || '');
  if (!text.trim()) return true;
  if (UPPER_VALAIS.test(text)) return false;
  if (ROMAND_CANTONS.test(text) || locationMatches(text, profile)) return true;
  return text.replace(COUNTRY_ONLY, '').replace(/[^\p{L}]/gu, '') === '';
}

// matchCategory : 'primary' (métier visé + mention junior/stage),
// 'secondary' (métier visé, séniorité non précisée), 'excluded' sinon.
function classifyListing(listing, profile) {
  const title = listing.title || '';
  const extra = listing.raw_extra || {};
  const description = [extra.description, extra.description_snippet, extra.description_full]
    .filter((v) => typeof v === 'string').join(' ');

  const roles = matchedRoles(title, profile);
  const level = seniority(title, description);
  const inRomandie = isRomandieLocation(listing.location, profile);

  let matchCategory = 'excluded';
  if (roles.length > 0 && level !== 'senior' && inRomandie) {
    matchCategory = level === 'junior' ? 'primary' : 'secondary';
  }

  const matchScore = roles.length * 3
    + (level === 'junior' ? 2 : 0)
    + (locationMatches(listing.location, profile) ? 1 : 0);

  return { matchCategory, matchScore, keywordsMatched: roles, seniority: level };
}

  const profile = $('Loop Over Items').first().json;

  // Une même offre remonte pour plusieurs villes de recherche (Genève et
  // Lausanne couvrent Nyon) : on ne la garde qu'une fois par source.
  const seen = new Set();
  return items
    .map(item => {
      const target = classifyListing(item.json, profile);
      return {
        json: {
          ...item.json,
          matchScore: target.matchScore,
          matchCategory: target.matchCategory,
          foreignLanguage: detectForeignLanguage(item.json),
          locationIncomplete: !item.json.location,
          keywordsMatched: target.keywordsMatched,
          searchProfileId: profile.id,
        },
      };
    })
    .filter(item => item.json.matchCategory !== 'excluded')
    .filter(item => {
      const key = item.json.source + '|' + item.json.source_id;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => b.json.matchScore - a.json.matchScore);

// Deux appels DeepL séparés (un pour le titre, un pour la description) au
  // lieu d'un seul appel avec deux paramètres "text" — n8n construit le
  // corps form-urlencoded à partir d'un objet clé/valeur, donc deux entrées
  // nommées "text" s'écrasaient silencieusement l'une l'autre et seule la
  // traduction de la description était renvoyée, stockée à tort comme titre
  // (ex: "Nous ouvrons un poste d'IT Tooling / DevOps Specialist pour...").
  const original = $('Filter by profile').item.json;
  const titleTranslations = $('Traduction Deepl').item.json.translations || [];
  const descTranslations = $json.translations || [];

  return {
    json: {
      ...original,
      title: titleTranslations[0] ? titleTranslations[0].text : original.title,
      raw_extra: {
        ...original.raw_extra,
        description_fr: descTranslations[0] ? descTranslations[0].text : null,
        title_original: original.title,
      },
    },
  };

function decodeEntities(s) {
  var out = String(s || '');
  out = out.split('&nbsp;').join(' ');
  out = out.split('&amp;').join('&');
  out = out.split('&lt;').join('<');
  out = out.split('&gt;').join('>');
  out = out.split('&quot;').join('"');
  out = out.split('&#39;').join("'");
  return out;
}

function stripTags(s) {
  return String(s || '').replace(/<[^>]*>/g, ' ');
}

function cleanText(s) {
  var out = decodeEntities(s);
  out = stripTags(out);
  out = out.replace(/\s+/g, ' ').trim();
  return out;
}

function truncate(s, max) {
  if (s.length <= max) return s;
  return s.slice(0, max).trim() + '…';
}

function escapeHtml(s) {
  var out = String(s || '');
  out = out.split('&').join('&amp;');
  out = out.split('<').join('&lt;');
  out = out.split('>').join('&gt;');
  out = out.split('"').join('&quot;');
  out = out.split("'").join('&#39;');
  return out;
}

function safeUrl(u) {
  var s = String(u || '').trim();
  return /^https?:\/\/[^\s"'<>]+$/i.test(s) ? s : '#';
}

function getDisplayTitle(item) {
  var raw = item.raw_extra || {};
  var original = raw.title_original;
  if (original && String(original).trim().length > 0) {
    return original;
  }
  return item.title;
}

var JUNIOR_REGEX = new RegExp(
  '\\b(junior|intern|internship|apprenti|apprentissage|stagiaire|' +
  'trainee|graduate|entry.level|working student)\\b',
  'i'
);

function isJuniorOrIntern(item) {
  var text = cleanText(getDisplayTitle(item));
  return JUNIOR_REGEX.test(text);
}

function sortJuniorFirst(list) {
  return list
    .map(function (item, idx) { return { item: item, idx: idx }; })
    .sort(function (a, b) {
      var aJunior = isJuniorOrIntern(a.item) ? 0 : 1;
      var bJunior = isJuniorOrIntern(b.item) ? 0 : 1;
      if (aJunior !== bJunior) return aJunior - bJunior;
      return a.idx - b.idx;
    })
    .map(function (wrapped) { return wrapped.item; });
}

function buildCard(item, accent) {
  var title = escapeHtml(truncate(cleanText(getDisplayTitle(item)), 140));
  var company = escapeHtml(cleanText(item.company || 'Entreprise non précisée'));
  var location = item.location
    ? escapeHtml(cleanText(item.location))
    : 'Localisation non précisée';
  var badge = '';
  if (item.foreign_language && item.foreign_language !== 'fr') {
    var b = [];
    b.push('<span style="display:inline-block;background:#f0f0f5;color:#6b6b7a;');
    b.push('font-size:11px;padding:2px 8px;border-radius:10px;margin-left:8px;">');
    b.push('EN → FR</span>');
    badge = b.join('');
  }
  var juniorBadge = '';
  if (isJuniorOrIntern(item)) {
    var jb = [];
    jb.push('<span style="display:inline-block;background:#e8f8ef;color:#1a7f4b;');
    jb.push('font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;');
    jb.push('margin-left:8px;">JUNIOR/INTERN</span>');
    juniorBadge = jb.join('');
  }
  var row = [];
  row.push('<tr><td style="padding:16px 20px;border-bottom:1px solid #ececf1;">');
  row.push('<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td>');
  row.push('<div style="font-size:15px;line-height:1.4;color:#1a1a2e;font-weight:600;">');
  row.push(title);
  row.push(badge);
  row.push(juniorBadge);
  row.push('</div>');
  row.push('<div style="font-size:13px;color:#6b6b7a;margin-top:4px;">');
  row.push(company);
  row.push(' · ');
  row.push(location);
  row.push('</div>');
  row.push('<div style="margin-top:10px;">');
  row.push('<a href="');
  row.push(escapeHtml(safeUrl(item.url)));
  row.push('" style="display:inline-block;font-size:13px;font-weight:600;color:#fff;');
  row.push('background:');
  row.push(accent);
  row.push(';text-decoration:none;padding:6px 14px;border-radius:6px;">');
  row.push('Voir l\'offre →</a>');
  row.push('</div>');
  row.push('</td></tr></table>');
  row.push('</td></tr>');
  return row.join('');
}

function buildSection(label, count, accent, cardsHtml) {
  if (count === 0) return '';
  var out = [];
  out.push('<tr><td style="padding:24px 20px 8px 20px;">');
  out.push('<span style="font-size:12px;font-weight:700;letter-spacing:0.06em;');
  out.push('text-transform:uppercase;color:');
  out.push(accent);
  out.push(';">');
  out.push(escapeHtml(label));
  out.push(' (');
  out.push(String(count));
  out.push(')</span>');
  out.push('</td></tr>');
  out.push(cardsHtml);
  return out.join('');
}

var primary = [];
var secondary = [];

for (var i = 0; i < items.length; i++) {
  var j = items[i].json;
  // SELECT offers a alwaysOutputData=true pour qu'un jour sans nouvelle
  // offre produise quand même un item (vide) et donc un email "0 offre"
  // au lieu qu'aucun mail ne parte — ce placeholder n'a pas d'id, on
  // l'ignore ici pour ne pas l'afficher comme une fausse offre.
  if (!j || !j.id) continue;
  if (j.match_category === 'primary') {
    primary.push(j);
  } else {
    secondary.push(j);
  }
}

var today = new Date();
var dd = String(today.getDate()).padStart(2, '0');
var mm = String(today.getMonth() + 1).padStart(2, '0');
var yyyy = today.getFullYear();
