}

    // API publique SmartRecruiters : toutes les offres du CERN en un appel (55 au
    // 05.10.2026, limite 100), indépendamment du mot-clé — d'où executeOnce sur
    // "CERN Search" (1 appel par profil au lieu d'1 par mot-clé). Le tri par
    // mot-clé et par lieu est laissé à "Filter by profile", comme partout.
    const input = items[0].json;
    if (!input || !Array.isArray(input.content)) {
      return [{ json: { __sourceError: true, source: 'CERN', message: 'réponse inattendue — ' + JSON.stringify(input).slice(0, 500) } }];
    }
    return input.content.map(raw => ({ json: normalizeCernPosting(raw) }));

function decodeEntities(s) {
  return String(s || '')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function firstMatch(html, pattern) {
  const m = html.match(pattern);
  return m ? decodeEntities(m[1]) : null;
}

// L'endpoint invité renvoie une liste de <li> contenant chacun une carte
// d'offre en HTML (pas de JSON). L'ID stable est dans data-entity-urn ; l'URL
// de la carte porte des paramètres de tracking (refId, trackingId) qui changent
// à chaque appel, donc on reconstruit une URL canonique à partir de l'ID.
function parseLinkedinCards(html) {
  return String(html || '')
    .split('<li>')
    .slice(1)
    .map((card) => {
      const id = firstMatch(card, /data-entity-urn="urn:li:jobPosting:(\d+)"/);
      if (!id) return null;
      return {
        source: 'linkedin.com',
        source_id: id,
        title: firstMatch(card, /<h3 class="base-search-card__title">([\s\S]*?)<\/h3>/),
        company: firstMatch(card, /<h4 class="base-search-card__subtitle">[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/),
        url: 'https://www.linkedin.com/jobs/view/' + id,
        location: firstMatch(card, /<span class="job-search-card__location">([\s\S]*?)<\/span>/),
        posted_at: firstMatch(card, /datetime="(\d{4}-\d{2}-\d{2})"/),
        raw_extra: {},
      };
    })
    .filter((job) => job && job.title);
}

    // Endpoint invité (sans compte) : 10 cartes HTML par mot-clé, offres publiées
    // dans les 7 derniers jours (f_TPR=r604800 — le pipeline ne tourne pas le
    // week-end, une fenêtre de 24 h en perdrait). Un item par mot-clé en entrée.
    // Une page sans carte = zéro résultat. Un item d'erreur HTTP (429, blocage,
    // timeout via onError: continueRegularOutput) ne fait plus jeter les
    // autres villes : leurs offres passent, et un marqueur d'erreur part en
    // plus vers l'alerte email ("If LinkedIn OK" route chaque item à part).
    const failed = items.filter(item => item.json && item.json.error);
    const seen = new Set();
    const jobs = items
      .filter(item => !(item.json && item.json.error))
      .flatMap(item => parseLinkedinCards(item.json.data))
      .filter(job => !seen.has(job.source_id) && seen.add(job.source_id))
      .map(job => ({ json: job }));
    if (failed.length > 0) {
      jobs.push({ json: { __sourceError: true, source: 'LinkedIn', message: failed.length + '/' + items.length
        + ' requête(s) en échec — ' + JSON.stringify(failed[0].json.error).slice(0, 500) } });
    }
    return jobs;

// swissdevjobs.ch expose toutes ses offres (toute la Suisse, toutes technos)
// en un seul appel JSON non authentifié : GET https://swissdevjobs.ch/api/jobsLight.
// Pas de recherche par mot-clé ni par lieu côté source : c'est "Filter by
// profile" qui fait tout le tri, comme pour les autres sources.
//
// Un enregistrement brut ressemble à :
//   { _id, name, company, actualCity, cityCategory, jobUrl, activeFrom,
//     workplace, jobType, expLevel, annualSalaryFrom, annualSalaryTo,
//     language, filterTags: [...] }
// L'URL publique d'une offre est https://swissdevjobs.ch/jobs/<jobUrl>.
function normalizeSwissDevJobsItem(raw) {
  return {
    source: 'swissdevjobs.ch',
    source_id: raw._id,
    title: raw.name,
    company: raw.company || null,
    url: 'https://swissdevjobs.ch/jobs/' + raw.jobUrl,
    // actualCity est la ville réelle ; cityCategory est un regroupement
    // (ex: "Lausanne" pour Renens), moins précis pour l'exclusion par lieu.
    location: raw.actualCity || null,
    // activeFrom est en heure locale suisse ("2026-10-02T00:00:00.000+02:00") :
    // on garde la date telle quelle plutôt que de la convertir en UTC, ce qui
    // la décalerait au jour précédent.
    posted_at: raw.activeFrom ? raw.activeFrom.slice(0, 10) : null,
    raw_extra: {
      salary_min: raw.annualSalaryFrom || null,
      salary_max: raw.annualSalaryTo || null,
      workplace: raw.workplace || null,
      job_type: raw.jobType || null,
      exp_level: raw.expLevel || null,
      language: raw.language || null,
      tags: raw.filterTags || [],
    },
  };
}

// Endpoint JSON public : toutes les offres tech de Suisse en un appel (~220),
// d'où executeOnce sur "swissdevjobs Search" (1 appel par profil). n8n éclate
// le tableau JSON de la réponse en un item par offre ; un item d'erreur HTTP
// (onError: continueRegularOutput) ou une offre sans _id = panne signalée.
if (items.length === 0) return [];
const malformed = items.find(item => !item.json || item.json.error || !item.json._id);
if (malformed) {
  return [{ json: { __sourceError: true, source: 'swissdevjobs', message: 'réponse inattendue — ' + JSON.stringify(malformed.json).slice(0, 500) } }];
}
return items.map(item => ({ json: normalizeSwissDevJobsItem(item.json) }));

// Les mots-clés du profil sont les postes visés ("junior data engineer"),
// mais les sources sont interrogées sans "junior" : sur jobs.ch à Genève,
// "junior data engineer" renvoie 2 offres contre 66 pour "data engineer",
// la plupart des postes ouverts aux juniors ne portant pas la mention. La
// séniorité est filtrée ensuite par "Filter by profile".
return items.map(item => ({
  json: { ...item.json, searchTerm: String(item.json.keywords).replace(/^\s*junior\s+/i, '').trim() },
}));

// Une recherche par ville pour les sources qui filtrent par localité :
// une seule ville (Genève) ne couvrait ni Fribourg, ni Neuchâtel, ni le
// Valais. Chaque ville est cherchée avec un rayon quand l'API en accepte un
// (Lausanne couvre Vevey et Montreux, Sion couvre Martigny).
const SEARCH_CITIES = ['Genève', 'Lausanne', 'Fribourg', 'Neuchâtel', 'Sion'];
return items.flatMap(item =>
  SEARCH_CITIES.map(city => ({ json: { ...item.json, searchLocation: city } }))
);
